// ============================================================================
// ETHERCAT_apb: APB4 register wrapper around ETHERCAT_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/ETHERCAT.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/ETHERCAT.md
// ============================================================================
module ETHERCAT_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic rx_dv,
  input logic [7:0] rx_d,
  output logic tx_dv,
  output logic [7:0] tx_d
);
  localparam logic [31:0] ID_VALUE = 32'hEC470100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [9:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd10) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_host_rd;
  logic          c_host_wr;
  logic [15:0]   c_host_addr;
  logic [7:0]    c_host_wdata;
  logic [7:0]    c_host_rdata;
  logic          c_fr_done;
  logic          c_fr_fcs_ok;
  logic          c_fr_ecat;
  logic [7:0]    c_fr_dgrams;
  logic [7:0]    c_fr_wkc;
  ETHERCAT_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .rx_dv(rx_dv),
    .rx_d(rx_d),
    .tx_dv(tx_dv),
    .tx_d(tx_d),
    .host_rd(c_host_rd),
    .host_wr(c_host_wr),
    .host_addr(c_host_addr),
    .host_wdata(c_host_wdata),
    .host_rdata(c_host_rdata),
    .fr_done(c_fr_done),
    .fr_fcs_ok(c_fr_fcs_ok),
    .fr_ecat(c_fr_ecat),
    .fr_dgrams(c_fr_dgrams),
    .fr_wkc(c_fr_wkc)
  );

  // ---------------- registers ----------------
  logic [1:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [15:0] r_MEM_ADDR;   // 12'h014 MEM_ADDR
  logic [7:0] r_MEM_WDATA;   // 12'h018 MEM_WDATA
  logic [1:0] p_CMD;   // 12'h01C CMD (pulses)
  logic [17:0] h_FRAME;   // 12'h024 FRAME holding register
  logic avail_FRAME;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_MEM_ADDR <= 16'h0;
      r_MEM_WDATA <= 8'h0;
      p_CMD <= '0;
      h_FRAME <= '0;
      avail_FRAME <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[1:0] & wmask[1:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[1:0]) | (PWDATA[1:0] & wmask[1:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_MEM_ADDR <= (r_MEM_ADDR & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[6]) r_MEM_WDATA <= (r_MEM_WDATA & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
      p_CMD <= (wr && hit[7]) ? PWDATA[1:0] & wmask[1:0] : '0;
      if (c_fr_done && (!avail_FRAME || (rd && hit[9]))) begin
        h_FRAME[0:0] <= c_fr_fcs_ok;
        h_FRAME[1:1] <= c_fr_ecat;
        h_FRAME[9:2] <= c_fr_dgrams[7:0];
        h_FRAME[17:10] <= c_fr_wkc[7:0];
        avail_FRAME <= 1'b1;
      end else if (rd && hit[9]) avail_FRAME <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_host_addr = r_MEM_ADDR[15:0];
  assign c_host_wdata = r_MEM_WDATA[7:0];
  assign c_host_wr = p_CMD[0:0];
  assign c_host_rd = p_CMD[1:1];

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_fr_done & (~avail_FRAME | (rd & hit[9]));
    irq_set[1] = c_fr_done & avail_FRAME & ~(rd & hit[9]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [0:0] flags = {avail_FRAME};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_MEM_ADDR);
      10'd6: apb_rdata = 32'(r_MEM_WDATA);
      10'd8: apb_rdata = 32'({c_host_rdata});
      10'd9: apb_rdata = 32'(h_FRAME);
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
